ALTER TYPE "OrderStatus" ADD VALUE IF NOT EXISTS 'BILLED';
ALTER TYPE "OrderStatus" ADD VALUE IF NOT EXISTS 'PAID';
ALTER TABLE "KOT" ADD COLUMN "idempotencyKey" TEXT;
CREATE TYPE "BillStatus" AS ENUM ('OPEN','PAID','VOID');
CREATE TYPE "PaymentMethod" AS ENUM ('CASH','CARD','UPI','OTHER');
CREATE TYPE "PaymentStatus" AS ENUM ('SUCCESS','VOID','REFUNDED');
CREATE TYPE "PrinterConnection" AS ENUM ('NETWORK','USB','LOCAL_AGENT','BROWSER');
CREATE TYPE "PrinterPurpose" AS ENUM ('BILL','KOT','KITCHEN');
CREATE TYPE "PrintDocumentType" AS ENUM ('BILL','RECEIPT','KOT','TEST');
CREATE TYPE "PrintJobStatus" AS ENUM ('QUEUED','PRINTING','PRINTED','FAILED','CANCELLED');
CREATE TABLE "BillSequence" ("branchId" TEXT NOT NULL, "nextNumber" INTEGER NOT NULL DEFAULT 1, CONSTRAINT "BillSequence_pkey" PRIMARY KEY ("branchId"));
CREATE TABLE "Bill" ("id" TEXT NOT NULL, "branchId" TEXT NOT NULL, "orderId" TEXT NOT NULL, "billNumber" TEXT NOT NULL, "subtotal" DECIMAL(12,2) NOT NULL, "discount" DECIMAL(12,2) NOT NULL DEFAULT 0, "tax" DECIMAL(12,2) NOT NULL DEFAULT 0, "serviceCharge" DECIMAL(12,2) NOT NULL DEFAULT 0, "deliveryCharge" DECIMAL(12,2) NOT NULL DEFAULT 0, "total" DECIMAL(12,2) NOT NULL, "status" "BillStatus" NOT NULL DEFAULT 'OPEN', "idempotencyKey" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Bill_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Payment" ("id" TEXT NOT NULL, "billId" TEXT NOT NULL, "method" "PaymentMethod" NOT NULL, "amount" DECIMAL(12,2) NOT NULL, "status" "PaymentStatus" NOT NULL DEFAULT 'SUCCESS', "reference" TEXT, "idempotencyKey" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Payment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Printer" ("id" TEXT NOT NULL, "branchId" TEXT NOT NULL, "name" TEXT NOT NULL, "type" TEXT NOT NULL, "connectionType" "PrinterConnection" NOT NULL DEFAULT 'BROWSER', "ipAddress" TEXT, "port" INTEGER, "paperWidth" INTEGER NOT NULL DEFAULT 80, "purpose" "PrinterPurpose" NOT NULL, "station" TEXT, "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Printer_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PrintJob" ("id" TEXT NOT NULL, "branchId" TEXT NOT NULL, "documentType" "PrintDocumentType" NOT NULL, "orderId" TEXT, "kotId" TEXT, "billId" TEXT, "printerId" TEXT, "status" "PrintJobStatus" NOT NULL DEFAULT 'QUEUED', "attemptCount" INTEGER NOT NULL DEFAULT 0, "idempotencyKey" TEXT, "errorMessage" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "printedAt" TIMESTAMP(3), CONSTRAINT "PrintJob_pkey" PRIMARY KEY ("id"));
ALTER TABLE "BillSequence" ADD CONSTRAINT "BillSequence_branchId_fkey" FOREIGN KEY ("branchId") REFERENCES "Branch"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Bill" ADD CONSTRAINT "Bill_branchId_fkey" FOREIGN KEY ("branchId") REFERENCES "Branch"("id") ON DELETE RESTRICT ON UPDATE CASCADE, ADD CONSTRAINT "Bill_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "Order"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Payment" ADD CONSTRAINT "Payment_billId_fkey" FOREIGN KEY ("billId") REFERENCES "Bill"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Printer" ADD CONSTRAINT "Printer_branchId_fkey" FOREIGN KEY ("branchId") REFERENCES "Branch"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "PrintJob" ADD CONSTRAINT "PrintJob_branchId_fkey" FOREIGN KEY ("branchId") REFERENCES "Branch"("id") ON DELETE CASCADE ON UPDATE CASCADE, ADD CONSTRAINT "PrintJob_printerId_fkey" FOREIGN KEY ("printerId") REFERENCES "Printer"("id") ON DELETE SET NULL ON UPDATE CASCADE, ADD CONSTRAINT "PrintJob_billId_fkey" FOREIGN KEY ("billId") REFERENCES "Bill"("id") ON DELETE SET NULL ON UPDATE CASCADE;
CREATE UNIQUE INDEX "Bill_billNumber_key" ON "Bill"("billNumber"); CREATE UNIQUE INDEX "Bill_orderId_key" ON "Bill"("orderId"); CREATE UNIQUE INDEX "Bill_branchId_idempotencyKey_key" ON "Bill"("branchId","idempotencyKey"); CREATE UNIQUE INDEX "Payment_billId_idempotencyKey_key" ON "Payment"("billId","idempotencyKey"); CREATE UNIQUE INDEX "PrintJob_branchId_idempotencyKey_key" ON "PrintJob"("branchId","idempotencyKey"); CREATE UNIQUE INDEX "KOT_branchId_idempotencyKey_key" ON "KOT"("branchId","idempotencyKey");
CREATE INDEX "Bill_branchId_status_createdAt_idx" ON "Bill"("branchId","status","createdAt"); CREATE INDEX "Payment_billId_createdAt_idx" ON "Payment"("billId","createdAt"); CREATE INDEX "Printer_branchId_purpose_isActive_idx" ON "Printer"("branchId","purpose","isActive"); CREATE INDEX "PrintJob_branchId_status_createdAt_idx" ON "PrintJob"("branchId","status","createdAt");
